import { createClient } from '@sanity/client';

interface Post {
  _id: string;
  title: string;
  slug: { current: string };
  publishedAt: string;
  excerpt: string;
  author: {
    name: string;
    imageUrl: string | null;
  };
}

const client = createClient({
  projectId: process.env.SANITY_PROJECT_ID!,
  dataset: process.env.SANITY_DATASET ?? 'production',
  apiVersion: '2024-01-01',
  useCdn: true,
});

async function getPosts(limit = 10): Promise<Post[]> {
  const query = `
    *[_type == "post" && defined(publishedAt)] | order(publishedAt desc) [0...$limit] {
      _id,
      title,
      slug,
      publishedAt,
      excerpt,
      author-> {
        name,
        "imageUrl": image.asset->url
      }
    }
  `;

  const posts = await client.fetch<Post[]>(query, { limit: limit - 1 });
  return posts;
}

const posts = await getPosts(10);
console.log('Posts:', posts);

import { createClient } from '@sanity/client';

interface NewPost {
  title: string;
  slug: string;
  body: string;
  authorId: string;
}

const client = createClient({
  projectId: process.env.SANITY_PROJECT_ID!,
  dataset: process.env.SANITY_DATASET ?? 'production',
  apiVersion: '2024-01-01',
  useCdn: false, // must be false for write operations
  token: process.env.SANITY_API_TOKEN!, // write token required
});

async function createPost(data: NewPost) {
  const doc = await client.create({
    _type: 'post',
    title: data.title,
    slug: {
      _type: 'slug',
      current: data.slug,
    },
    body: [
      {
        _type: 'block',
        _key: crypto.randomUUID(),
        children: [
          {
            _type: 'span',
            _key: crypto.randomUUID(),
            text: data.body,
            marks: [],
          },
        ],
        markDefs: [],
        style: 'normal',
      },
    ],
    author: {
      _type: 'reference',
      _ref: data.authorId,
    },
    publishedAt: new Date().toISOString(),
  });

  console.log('Created document with ID:', doc._id);
  return doc;
}

await createPost({
  title: 'Hello World',
  slug: 'hello-world',
  body: 'This is the first paragraph of my post.',
  authorId: 'author-document-id-here',
});
